// Usage: node scripts/try.mjs <extension dir> <profile dir> [url]
import { chromium } from "@playwright/test";

const [extDir, profileDir, url] = process.argv.slice(2);
if (!extDir || !profileDir) {
  console.error("usage: node scripts/try.mjs <extension dir> <profile dir> [url]");
  process.exit(2);
}

const context = await chromium.launchPersistentContext(profileDir, {
  channel: "chromium", // branded Chrome ≥137 can't load unpacked extensions from the CLI
  headless: false,
  viewport: null,
  args: [
    `--disable-extensions-except=${extDir}`,
    `--load-extension=${extDir}`,
    "--no-first-run",
    "--start-maximized",
  ],
});
const page = context.pages()[0] ?? (await context.newPage());
await page.goto(url || "chrome://extensions");
console.log("✓ Chromium open — pin the extension from the puzzle-piece menu, then click it.");
console.log("  Close the browser window (or Ctrl-C) to finish.");

const done = () => context.close().finally(() => process.exit(0));
process.on("SIGINT", done);
process.on("SIGTERM", done);
await new Promise((resolve) => context.on("close", resolve));
